create or replace function public.vc_record_inbox_event(webhook_secret text,provider_instance text,event_name text,conversation_jid text default null,sent_by_us boolean default false) returns void language plpgsql security definer set search_path='' as $$ declare w uuid;n_id uuid;begin
if event_name not in('messages.upsert','messages.update','send.message','send.message.update','chats.upsert','chats.update','connection.update')then return;end if;
select c.workspace_id,c.number_id into w,n_id from public.vc_webhook_configs c join public.vc_numbers n on n.id=c.number_id where n.instance_name=provider_instance and c.secret=webhook_secret;if n_id is null then raise exception 'Invalid webhook secret';end if;
insert into public.vc_inbox_events(workspace_id,number_id,event)values(w,n_id,event_name);
if conversation_jid is not null and conversation_jid ~ '^([1-9][0-9]{7,24}@(s\.whatsapp\.net|lid)|[0-9-]{8,40}@g\.us)$' then insert into public.vc_conversations(workspace_id,number_id,remote_jid,unread_count,last_message_at)values(w,n_id,conversation_jid,case when sent_by_us then 0 else 1 end,now())on conflict(number_id,remote_jid)do update set unread_count=case when sent_by_us then public.vc_conversations.unread_count else public.vc_conversations.unread_count+1 end,last_message_at=now(),updated_at=now();end if;
delete from public.vc_inbox_events where number_id=n_id and created_at<now()-interval '1 day';end $$;
